<template><div class="page-container"><el-card><template #header><div class="header"><span>打手等级分类</span><el-button type="primary" @click="edit()">新增分类</el-button></div></template><p class="tip">分类名称可自定义，排序值越小越靠前。停用后，该分类及其打手会从公开目录隐藏。</p><el-table v-loading="loading" :data="list" stripe><el-table-column prop="name" label="分类名称" min-width="180"/><el-table-column label="涨价比例" width="120"><template #default="{row}">{{ Number(row.priceIncreaseRate || 0) }}%</template></el-table-column><el-table-column prop="sortOrder" label="排序" width="100"/><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{ row.status===1?'启用':'停用' }}</el-tag></template></el-table-column><el-table-column label="抢单图形验证码" width="160"><template #default="{row}">{{ row.grabCaptchaRequired===0?'免验证':'需要验证' }}</template></el-table-column><el-table-column label="操作" width="200"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="visible" :title="form.id?'编辑等级分类':'新增等级分类'" width="440px"><el-form label-width="80px"><el-form-item label="名称"><el-input v-model="form.name" maxlength="30" placeholder="如金牌打手、魔王护、高级打手"/></el-form-item><el-form-item label="涨价比例"><el-input-number v-model="form.priceIncreaseRate" :min="0" :max="100" :precision="2"/><span style="margin-left:8px">%</span><div class="tip" style="width:100%;margin:8px 0 0">商品100元，涨价10%后为110元；0表示不涨价。</div></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder" :min="0" :max="99999" :precision="0"/></el-form-item><el-form-item label="抢单验证"><el-switch v-model="form.grabCaptchaRequired" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>
import {ref,reactive,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {playerLevelList,playerLevelCreate,playerLevelUpdate,playerLevelDelete} from '@/api/business'
const list=ref([]),loading=ref(false),visible=ref(false),saving=ref(false),form=reactive({id:null,name:'',sortOrder:10,status:1,grabCaptchaRequired:1,priceIncreaseRate:0})
onMounted(load)
async function load(){loading.value=true;try{list.value=(await playerLevelList()).data||[]}finally{loading.value=false}}
function edit(row){Object.assign(form,row?{id:row.id,name:row.name,sortOrder:row.sortOrder,status:row.status,grabCaptchaRequired:row.grabCaptchaRequired??1,priceIncreaseRate:Number(row.priceIncreaseRate||0)}:{id:null,name:'',sortOrder:10,status:1,grabCaptchaRequired:1,priceIncreaseRate:0});visible.value=true}
async function save(){if(!form.name.trim())return ElMessage.warning('请输入分类名称');if(!Number.isFinite(form.priceIncreaseRate))return ElMessage.warning('请输入涨价比例');saving.value=true;try{const data={name:form.name.trim(),sortOrder:form.sortOrder,status:form.status,grabCaptchaRequired:form.grabCaptchaRequired,priceIncreaseRate:form.priceIncreaseRate};if(form.id)await playerLevelUpdate(form.id,data);else await playerLevelCreate(data);ElMessage.success('已保存');visible.value=false;load()}finally{saving.value=false}}
async function remove(row){try{await ElMessageBox.confirm(`删除「${row.name}」？分类下仍有打手时无法删除，可改为停用。`,'删除分类',{type:'warning'})}catch(_){return}await playerLevelDelete(row.id);ElMessage.success('已删除');load()}
</script>
<style scoped>.header{display:flex;justify-content:space-between;align-items:center}.tip{color:#858992;font-size:13px;margin:0 0 20px;line-height:1.7}</style>
